package vn.sland.controller;

import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import vn.sland.service.AffiliateService;import vn.sland.util.WebUtil;

@Controller
public class AffiliateController extends BaseController {
 private final AffiliateService affiliate;public AffiliateController(AffiliateService affiliate){this.affiliate=affiliate;}
 @GetMapping("/affiliate_register.php")String register(Model m,HttpSession s){if(!WebUtil.logged(s))return "redirect:/login.php";base(m,s,"Đăng ký cộng tác viên");m.addAttribute("affiliate",affiliate.byUser(WebUtil.longv(s.getAttribute("user_id"))));return "affiliate_register";}
 @PostMapping("/affiliate_register.php")String registerPost(@RequestParam(name="bank_name",required=false,defaultValue="")String bank,@RequestParam(name="bank_account",required=false,defaultValue="")String account,@RequestParam(name="bank_owner",required=false,defaultValue="")String owner,Model m,HttpSession s){if(!WebUtil.logged(s))return "redirect:/login.php";String err=affiliate.register(WebUtil.longv(s.getAttribute("user_id")),bank,account,owner);base(m,s,"Đăng ký cộng tác viên");m.addAttribute("affiliate",affiliate.byUser(WebUtil.longv(s.getAttribute("user_id"))));if(err!=null)m.addAttribute("error",err);else m.addAttribute("success","Đăng ký CTV thành công, vui lòng chờ admin duyệt.");return "affiliate_register";}
 @GetMapping("/affiliate.php")String dash(Model m,HttpSession s){if(!WebUtil.logged(s))return "redirect:/login.php";long uid=WebUtil.longv(s.getAttribute("user_id"));var a=affiliate.byUser(uid);if(a==null)return "redirect:/affiliate_register.php";base(m,s,"Cộng tác viên GS LUXURY");m.addAttribute("affiliate",a);m.addAttribute("commissions",affiliate.commissions(WebUtil.longv(a.get("id"))));m.addAttribute("withdrawals",affiliate.withdrawals(WebUtil.longv(a.get("id"))));// Đọc flash message từ session sau redirect
     Object flash=s.getAttribute("aff_flash");if(flash!=null){String msg=String.valueOf(flash);if(msg.contains("thành công")||msg.contains("gửi")||msg.contains("đã được"))m.addAttribute("success",msg);else m.addAttribute("error",msg);s.removeAttribute("aff_flash");}return "affiliate";}
 @PostMapping("/affiliate.php")String withdraw(@RequestParam String action,@RequestParam(required=false,defaultValue="0")double amount,@RequestParam(name="bank_name",required=false,defaultValue="")String bank,@RequestParam(name="bank_account",required=false,defaultValue="")String account,@RequestParam(name="bank_owner",required=false,defaultValue="")String owner,@RequestParam(required=false,defaultValue="")String note,Model m,HttpSession s){if(!WebUtil.logged(s))return "redirect:/login.php";if("withdraw".equals(action)){String err=affiliate.requestWithdrawal(WebUtil.longv(s.getAttribute("user_id")),amount,bank,account,owner,note);s.setAttribute("aff_flash",err==null?"Yêu cầu rút tiền đã được gửi.":err);}return "redirect:/affiliate.php";}
}
